-- Übungskatalog aus free-exercise-db (gemeinfrei). Erzeugt von tools/build-seed.mjs.
-- 200 Übungen, Teil 2 von 4. Deutsche Namen sind maschinell erzeugt und dürfen angepasst werden.
--
-- Das Skript ist wiederholbar: bereits vorhandene Katalogübungen (source + source_id)
-- werden aktualisiert (Namen, Muskelgruppen, Gerät, englische Anleitung). Ihre IDs bleiben
-- gleich, Pläne und Trainings bleiben also verknüpft. Deine eigenen Übungen und deine
-- deutschen Anleitungen (instructions_de) bleiben unberührt.
-- Die Übungen gehören dem ersten (einzigen) Nutzer in auth.users. Lege dein Konto
-- deshalb an, bevor du dieses Skript ausführst.

do $seed$
declare uid uuid;
begin
  select id into uid from auth.users order by created_at limit 1;
  if uid is null then
    raise exception 'Kein Nutzer in auth.users. Lege zuerst dein Konto an (Authentication > Users).';
  end if;

  insert into fit_exercises
    (user_id, source, source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  select uid, 'free-exercise-db', v.source_id, v.name_en, v.name_de, v.primary_muscles, v.secondary_muscles, v.equipment, v.instructions_en
  from (values
    ('Dumbbell_Scaption', 'Dumbbell Scaption', 'Kurzhantel-Scaption', array['shoulders']::text[], array['traps']::text[], 'dumbbell', array['This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.', 'Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.', 'Continue until your arms are parallel to the ground, and then return to the starting position.']::text[]),
    ('Dumbbell_Seated_One-Leg_Calf_Raise', 'Dumbbell Seated One-Leg Calf Raise', 'Sitzendes einbeiniges Wadenheben mit Kurzhantel', array['calves']::text[], '{}'::text[], 'dumbbell', array['Place a block on the floor about 12 inches from a flat bench.', 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.', 'Now place the ball of your left foot on the block. This will be your starting position.', 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.', 'Slowly return to the starting position, stretching as far down as possible.', 'Repeat for your prescribed number of repetitions and then repeat with the right leg.']::text[]),
    ('Dumbbell_Shoulder_Press', 'Dumbbell Shoulder Press', 'Kurzhantel-Schulterdrücken', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', array['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Shrug', 'Dumbbell Shrug', 'Kurzhantel-Schulterzucken', array['traps']::text[], '{}'::text[], 'dumbbell', array['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Side_Bend', 'Dumbbell Side Bend', 'Kurzhantel-Seitbeugen', array['abdominals']::text[], '{}'::text[], 'dumbbell', array['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.']::text[]),
    ('Dumbbell_Squat', 'Dumbbell Squat', 'Kurzhantel-Kniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'dumbbell', array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Squat_To_A_Bench', 'Dumbbell Squat To A Bench', 'Kurzhantel-Kniebeuge auf die Bank', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'dumbbell', array['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Dumbbell_Step_Ups', 'Dumbbell Step Ups', 'Kurzhantel-Step-ups', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'dumbbell', array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[]),
    ('Dumbbell_Tricep_Extension_-Pronated_Grip', 'Dumbbell Tricep Extension -Pronated Grip', 'Kurzhantel-Trizeps-Extension, Obergriff', array['triceps']::text[], '{}'::text[], 'dumbbell', array['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.', 'The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.', 'Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.', 'Then, exhale and use your triceps to return the weight to the starting position.']::text[]),
    ('EZ-Bar_Curl', 'EZ-Bar Curl', 'SZ-Stangen-Curl', array['biceps']::text[], '{}'::text[], 'e-z curl bar', array['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.', 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.', 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.', 'Then inhale and slowly lower the bar back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('EZ-Bar_Skullcrusher', 'EZ-Bar Skullcrusher', 'SZ-Stangen-Stirndrücken', array['triceps']::text[], array['forearms']::text[], 'e-z curl bar', array['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.', 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.', 'Lift the bar back to the starting position by extending the elbow and exhaling.', 'Repeat.']::text[]),
    ('Elbow_to_Knee', 'Elbow to Knee', 'Ellbogen zum Knie', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.', 'Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.', 'Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.']::text[]),
    ('Elevated_Back_Lunge', 'Elevated Back Lunge', 'Ausfallschritt rückwärts mit erhöhtem Fuß', array['quadriceps']::text[], array['glutes', 'hamstrings']::text[], 'barbell', array['Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.', 'Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.', 'Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.', 'Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.']::text[]),
    ('Elevated_Cable_Rows', 'Elevated Cable Rows', 'Rudern am Kabelzug mit erhöhten Füßen', array['lats']::text[], array['middle back', 'traps']::text[], 'cable', array['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.', 'Place it on the seat of the cable row machine.', 'Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Exercise_Ball_Crunch', 'Exercise Ball Crunch', 'Crunch auf dem Gymnastikball', array['abdominals']::text[], '{}'::text[], 'exercise ball', array['Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).', 'Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.', 'With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.', 'As you inhale, go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Exercise_Ball_Pull-In', 'Exercise Ball Pull-In', 'Pull-In auf dem Gymnastikball', array['abdominals']::text[], '{}'::text[], 'exercise ball', array['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.', 'Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.', 'While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.', 'Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Extended_Range_One-Arm_Kettlebell_Floor_Press', 'Extended Range One-Arm Kettlebell Floor Press', 'Einarmiges Kettlebell-Bodendrücken (großer Bewegungsumfang)', array['chest']::text[], array['shoulders', 'triceps']::text[], 'kettlebells', array['Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.', 'Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.']::text[]),
    ('External_Rotation', 'External Rotation', 'Außenrotation', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.', 'Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
    ('External_Rotation_with_Band', 'External Rotation with Band', 'Außenrotation mit Band', array['shoulders']::text[], '{}'::text[], 'bands', array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[]),
    ('External_Rotation_with_Cable', 'External Rotation with Cable', 'Außenrotation am Kabelzug', array['shoulders']::text[], '{}'::text[], 'cable', array['Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.']::text[]),
    ('Face_Pull', 'Face Pull', 'Face Pull', array['shoulders']::text[], array['middle back']::text[], 'cable', array['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[]),
    ('Farmers_Walk', 'Farmer''s Walk', 'Farmer''s Walk', array['forearms']::text[], array['abdominals', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps']::text[], 'other', array['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[]),
    ('Finger_Curls', 'Finger Curls', 'Finger-Curls', array['forearms']::text[], '{}'::text[], 'barbell', array['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.', 'Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.', 'Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[]),
    ('Flat_Bench_Cable_Flyes', 'Flat Bench Cable Flyes', 'Fliegende am Kabelzug auf der Flachbank', array['chest']::text[], '{}'::text[], 'cable', array['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.', 'Lay flat on the bench and keep your feet on the ground.', 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.', 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.', 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.', 'Slowly come back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Flat_Bench_Leg_Pull-In', 'Flat Bench Leg Pull-In', 'Beinanziehen auf der Flachbank', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie on an exercise mat or a flat bench with your legs off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.', 'As you breathe in, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Flat_Bench_Lying_Leg_Raise', 'Flat Bench Lying Leg Raise', 'Liegendes Beinheben auf der Flachbank', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie with your back flat on a bench and your legs extended in front of you off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.', 'As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.', 'Now, as you inhale, slowly lower your legs back down to the starting position.']::text[]),
    ('Flexor_Incline_Dumbbell_Curls', 'Flexor Incline Dumbbell Curls', 'Flexor-Curl an der Schrägbank (Kurzhantel)', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.', 'Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.', 'Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.', 'Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.', 'As you inhale, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Floor_Glute-Ham_Raise', 'Floor Glute-Ham Raise', 'Glute-Ham-Raise am Boden', array['hamstrings']::text[], array['calves', 'glutes']::text[], null, array['You can use a partner for this exercise or brace your feet under something stable.', 'Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.', 'Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.', 'Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.']::text[]),
    ('Floor_Press', 'Floor Press', 'Bodendrücken', array['triceps']::text[], array['chest', 'shoulders']::text[], 'barbell', array['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[]),
    ('Floor_Press_with_Chains', 'Floor Press with Chains', 'Bodendrücken mit Ketten', array['triceps']::text[], array['chest', 'shoulders']::text[], 'barbell', array['Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.', 'Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[]),
    ('Flutter_Kicks', 'Flutter Kicks', 'Flutter Kicks', array['glutes']::text[], array['hamstrings']::text[], 'body only', array['On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.', 'Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.', 'Start the movement by lifting the left leg higher than the right leg.', 'Then lower the left leg as you lift the right leg.', 'Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.']::text[]),
    ('Forward_Drag_with_Press', 'Forward Drag with Press', 'Vorwärts ziehen mit Drücken (Schlitten)', array['chest']::text[], array['calves', 'glutes', 'hamstrings', 'quadriceps', 'shoulders', 'triceps']::text[], 'other', array['Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.', 'Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.']::text[]),
    ('Frankenstein_Squat', 'Frankenstein Squat', 'Frankenstein-Kniebeuge', array['quadriceps']::text[], array['abdominals', 'calves', 'glutes', 'hamstrings']::text[], 'barbell', array['This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.', 'Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.', 'Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.', 'Return to the upright position by driving through the front of the heel and extending the knees and hips.']::text[]),
    ('Freehand_Jump_Squat', 'Freehand Jump Squat', 'Sprung-Kniebeuge ohne Gewicht', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'body only', array['Cross your arms over your chest.', 'With your head up and your back straight, position your feet at shoulder width.', 'Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.', 'Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.', 'When you touch the floor again, immediately squat down and jump again.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Frog_Sit-Ups', 'Frog Sit-Ups', 'Frog-Sit-ups', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.', 'Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.', 'Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.', 'Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.', 'As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.', 'As you inhale, slowly lower back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Front_Barbell_Squat', 'Front Barbell Squat', 'Langhantel-Frontkniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Front_Barbell_Squat_To_A_Bench', 'Front Barbell Squat To A Bench', 'Langhantel-Frontkniebeuge auf die Bank', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Front_Cable_Raise', 'Front Cable Raise', 'Frontheben am Kabelzug', array['shoulders']::text[], '{}'::text[], 'cable', array['Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.', 'Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'Now as you inhale lower the arm back down slowly to the starting position.', 'Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.']::text[]),
    ('Front_Dumbbell_Raise', 'Front Dumbbell Raise', 'Kurzhantel-Frontheben', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[]),
    ('Front_Incline_Dumbbell_Raise', 'Front Incline Dumbbell Raise', 'Kurzhantel-Frontheben an der Schrägbank', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.', 'Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.', 'Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.', 'Lower the arms back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Front_Plate_Raise', 'Front Plate Raise', 'Frontheben mit Scheibe', array['shoulders']::text[], '{}'::text[], 'other', array['While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.', 'Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.', 'As you inhale, slowly lower the plate back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Front_Raise_And_Pullover', 'Front Raise And Pullover', 'Frontheben und Überzug', array['chest']::text[], array['lats', 'shoulders', 'triceps']::text[], 'barbell', array['Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.', 'Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.', 'Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.', 'Now return the barbell to the starting position by reversing the motion as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Front_Squat_Clean_Grip', 'Front Squat (Clean Grip)', 'Frontkniebeuge (Clean-Griff)', array['quadriceps']::text[], array['abdominals', 'glutes', 'hamstrings']::text[], 'barbell', array['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.', 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[]),
    ('Front_Squats_With_Two_Kettlebells', 'Front Squats With Two Kettlebells', 'Frontkniebeuge mit zwei Kettlebells', array['quadriceps']::text[], array['calves', 'glutes']::text[], 'kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.', 'Rise back up by driving through your heels and repeat.']::text[]),
    ('Front_Two-Dumbbell_Raise', 'Front Two-Dumbbell Raise', 'Frontheben mit zwei Kurzhanteln', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'As you inhale, lower the dumbbells back down slowly to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Full_Range-Of-Motion_Lat_Pulldown', 'Full Range-Of-Motion Lat Pulldown', 'Latziehen mit vollem Bewegungsumfang', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'cable', array['Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.', 'Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.']::text[]),
    ('Gironda_Sternum_Chins', 'Gironda Sternum Chins', 'Gironda-Brustbein-Klimmzüge', array['lats']::text[], array['biceps', 'middle back']::text[], 'other', array['Grasp the pull-up bar with a shoulder width underhand grip.', 'Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.', 'Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.', 'Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.', 'Slowly start going back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Glute_Ham_Raise', 'Glute Ham Raise', 'Glute-Ham-Raise', array['hamstrings']::text[], array['calves', 'glutes']::text[], 'machine', array['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.']::text[]),
    ('Glute_Kickback', 'Glute Kickback', 'Glute Kickback', array['glutes']::text[], array['hamstrings']::text[], 'body only', array['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.', 'Go back to the initial position as you inhale and now repeat with the left leg.', 'Continue to alternate legs until all of the recommended repetitions have been performed.']::text[]),
    ('Goblet_Squat', 'Goblet Squat', 'Goblet Squat', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'shoulders']::text[], 'kettlebells', array['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[]),
    ('Good_Morning', 'Good Morning', 'Good Morning', array['hamstrings']::text[], array['abdominals', 'glutes', 'lower back']::text[], 'barbell', array['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[]),
    ('Good_Morning_off_Pins', 'Good Morning off Pins', 'Good Morning von den Pins', array['hamstrings']::text[], array['abdominals', 'glutes', 'lower back']::text[], 'barbell', array['Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.']::text[]),
    ('Gorilla_Chin_Crunch', 'Gorilla Chin/Crunch', 'Gorilla-Klimmzug/Crunch', array['abdominals']::text[], array['biceps', 'lats']::text[], 'body only', array['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.', 'Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.', 'As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.', 'Slowly start to inhale as you return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hack_Squat', 'Hack Squat', 'Hackenschmidt-Kniebeuge (Hack Squat)', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hammer_Curls', 'Hammer Curls', 'Hammer-Curls', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hammer_Grip_Incline_DB_Bench_Press', 'Hammer Grip Incline DB Bench Press', 'Kurzhantel-Schrägbankdrücken, Hammergriff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'dumbbell', array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[]),
    ('Handstand_Push-Ups', 'Handstand Push-Ups', 'Handstand-Liegestütze', array['shoulders']::text[], array['triceps']::text[], 'body only', array['With your back to the wall bend at the waist and place both hands on the floor at shoulder width.', 'Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.', 'Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.', 'Push yourself back up slowly as you exhale until your elbows are nearly locked.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hang_Clean', 'Hang Clean', 'Umsetzen aus dem Hang', array['quadriceps']::text[], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps']::text[], 'barbell', array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[]),
    ('Hang_Clean_-_Below_the_Knees', 'Hang Clean - Below the Knees', 'Umsetzen aus dem Hang (unter den Knien)', array['quadriceps']::text[], array['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps']::text[], 'barbell', array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.', 'At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[]),
    ('Hang_Snatch', 'Hang Snatch', 'Reißen aus dem Hang', array['hamstrings']::text[], array['abdominals', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[], 'barbell', array['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.']::text[]),
    ('Hang_Snatch_-_Below_Knees', 'Hang Snatch - Below Knees', 'Reißen aus dem Hang (unter den Knien)', array['hamstrings']::text[], array['abdominals', 'calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[], 'barbell', array['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead, and then return the weight to the floor under control.']::text[]),
    ('Hanging_Bar_Good_Morning', 'Hanging Bar Good Morning', 'Good Morning mit hängender Stange', array['hamstrings']::text[], array['abdominals', 'glutes', 'lower back']::text[], 'barbell', array['Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.', 'Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.', 'Slowly lower the weight back to the starting position, where it is supported by the chains.']::text[]),
    ('Hanging_Leg_Raise', 'Hanging Leg Raise', 'Hängendes Beinheben', array['abdominals']::text[], '{}'::text[], 'body only', array['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hanging_Pike', 'Hanging Pike', 'Hängender Pike', array['abdominals']::text[], '{}'::text[], 'body only', array['Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.', 'Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.', 'Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.', 'Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Heaving_Snatch_Balance', 'Heaving Snatch Balance', 'Heaving Snatch Balance', array['quadriceps']::text[], array['abdominals', 'forearms', 'glutes', 'hamstrings', 'shoulders', 'triceps']::text[], 'barbell', array['This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.', 'Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.', 'Return to a standing position.']::text[]),
    ('High_Cable_Curls', 'High Cable Curls', 'Curls am hohen Kabelzug', array['biceps']::text[], '{}'::text[], 'cable', array['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.', 'Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.', 'Slowly bring back the arms to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hip_Extension_with_Bands', 'Hip Extension with Bands', 'Hüftstreckung mit Bändern', array['glutes']::text[], array['hamstrings']::text[], 'bands', array['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Facing the attachment point of the band, hold on to the column to stabilize yourself.', 'Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.', 'Return the leg to the starting position.']::text[]),
    ('Hip_Flexion_with_Band', 'Hip Flexion with Band', 'Hüftbeugung mit Band', array['quadriceps']::text[], '{}'::text[], 'bands', array['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Face away from the attachment point of the band.', 'Keeping your head and your chest up, raise your knee up to 90 degrees and pause.', 'Return the leg to the starting position.']::text[]),
    ('Hip_Lift_with_Band', 'Hip Lift with Band', 'Beckenheben mit Band', array['glutes']::text[], array['calves', 'hamstrings']::text[], 'bands', array['After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.', 'Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.', 'Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.', 'Pause at the top of the motion, and return to the starting position.']::text[]),
    ('Hyperextensions_Back_Extensions', 'Hyperextensions (Back Extensions)', 'Rückenstrecker (Hyperextensions)', array['lower back']::text[], array['glutes', 'hamstrings']::text[], 'other', array['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.', 'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.', 'Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Hyperextensions_With_No_Hyperextension_Bench', 'Hyperextensions With No Hyperextension Bench', 'Rückenstrecken ohne Hyperextension-Bank', array['lower back']::text[], array['glutes', 'hamstrings']::text[], 'body only', array['With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.', 'Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Barbell_Triceps_Extension', 'Incline Barbell Triceps Extension', 'Langhantel-Trizeps-Extension an der Schrägbank', array['triceps']::text[], array['forearms']::text[], 'barbell', array['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.', 'Lie back on an incline bench set at any angle between 45-75-degrees.', 'Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.', 'Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.', 'Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Bench_Pull', 'Incline Bench Pull', 'Rudern bäuchlings an der Schrägbank', array['middle back']::text[], array['lats', 'shoulders']::text[], 'barbell', array['Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.', 'Let the arms hang to your sides fully extended as they point to the floor.', 'Turn the wrists until your hands have a pronated (palms down) grip.', 'Now flare the elbows out. This will be your starting position.', 'As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter "T" at the top of the movement. Hold the contraction at the top for a second.', 'Slowly go back down to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Cable_Chest_Press', 'Incline Cable Chest Press', 'Schrägbankdrücken am Kabelzug', array['chest']::text[], array['shoulders', 'triceps']::text[], 'cable', array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to the starting position, keeping tension on the cables.']::text[]),
    ('Incline_Cable_Flye', 'Incline Cable Flye', 'Fliegende am Kabelzug, Schrägbank', array['chest']::text[], array['shoulders']::text[], 'cable', array['To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).', 'Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.', 'With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.', 'With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Incline_Dumbbell_Bench_With_Palms_Facing_In', 'Incline Dumbbell Bench With Palms Facing In', 'Kurzhantel-Schrägbankdrücken, neutraler Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'dumbbell', array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[]),
    ('Incline_Dumbbell_Curl', 'Incline Dumbbell Curl', 'Kurzhantel-Curl an der Schrägbank', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Dumbbell_Flyes', 'Incline Dumbbell Flyes', 'Kurzhantel-Fliegende an der Schrägbank', array['chest']::text[], array['shoulders']::text[], 'dumbbell', array['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Dumbbell_Flyes_-_With_A_Twist', 'Incline Dumbbell Flyes - With A Twist', 'Kurzhantel-Fliegende an der Schrägbank mit Drehung', array['chest']::text[], array['shoulders']::text[], 'dumbbell', array['Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Dumbbell_Press', 'Incline Dumbbell Press', 'Kurzhantel-Schrägbankdrücken', array['chest']::text[], array['shoulders', 'triceps']::text[], 'dumbbell', array['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[]),
    ('Incline_Hammer_Curls', 'Incline Hammer Curls', 'Hammer-Curls an der Schrägbank', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.', 'Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.', 'Continue to the top of the movement and pause, then slowly return to the start position.']::text[]),
    ('Incline_Inner_Biceps_Curl', 'Incline Inner Biceps Curl', 'Curl für den inneren Bizeps an der Schrägbank', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Hold a dumbbell in each hand and lie back on an incline bench.', 'The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.', 'Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.', 'After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Incline_Push-Up', 'Incline Push-Up', 'Liegestütz, Hände erhöht', array['chest']::text[], array['shoulders', 'triceps']::text[], 'body only', array['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.', 'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.', 'Push body up until arms are extended. Repeat.']::text[]),
    ('Incline_Push-Up_Close-Grip', 'Incline Push-Up Close-Grip', 'Liegestütz, Hände erhöht, enger Griff', array['triceps']::text[], array['chest', 'shoulders']::text[], 'body only', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands next to one another on the bar.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
    ('Incline_Push-Up_Medium', 'Incline Push-Up Medium', 'Liegestütz, Hände erhöht, mittlerer Griff', array['chest']::text[], array['abdominals', 'shoulders', 'triceps']::text[], 'body only', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
    ('Incline_Push-Up_Reverse_Grip', 'Incline Push-Up Reverse Grip', 'Liegestütz, Hände erhöht, Untergriff', array['chest']::text[], array['abdominals', 'shoulders', 'triceps']::text[], 'body only', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar palms up, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
    ('Incline_Push-Up_Wide', 'Incline Push-Up Wide', 'Liegestütz, Hände erhöht, weiter Griff', array['chest']::text[], array['abdominals', 'shoulders', 'triceps']::text[], 'body only', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands wider than shoulder width.', 'Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
    ('Internal_Rotation_with_Band', 'Internal Rotation with Band', 'Innenrotation mit Band', array['shoulders']::text[], '{}'::text[], 'bands', array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[]),
    ('Inverted_Row', 'Inverted Row', 'Umgekehrtes Rudern (Inverted Row)', array['middle back']::text[], array['lats']::text[], null, array['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[]),
    ('Inverted_Row_with_Straps', 'Inverted Row with Straps', 'Umgekehrtes Rudern mit Schlingen', array['middle back']::text[], array['biceps', 'lats']::text[], 'other', array['Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[]),
    ('Iron_Cross', 'Iron Cross', 'Iron Cross', array['shoulders']::text[], array['chest', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps']::text[], 'dumbbell', '{}'::text[]),
    ('Isometric_Neck_Exercise_-_Front_And_Back', 'Isometric Neck Exercise - Front And Back', 'Isometrisches Nackentraining, vorne und hinten', array['neck']::text[], '{}'::text[], 'body only', array['With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.', 'Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.']::text[]),
    ('Isometric_Neck_Exercise_-_Sides', 'Isometric Neck Exercise - Sides', 'Isometrisches Nackentraining, seitlich', array['neck']::text[], '{}'::text[], 'body only', array['With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.', 'Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head.']::text[]),
    ('Isometric_Wipers', 'Isometric Wipers', 'Isometrische Scheibenwischer', array['chest']::text[], array['abdominals', 'shoulders', 'triceps']::text[], 'body only', array['Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.', 'Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.', 'Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.', 'Repeat for the desired number of repetitions.']::text[]),
    ('JM_Press', 'JM Press', 'JM Press', array['triceps']::text[], array['chest', 'shoulders']::text[], 'barbell', array['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.', 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.', 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.', 'Now go back to the starting position and start over.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Jackknife_Sit-Up', 'Jackknife Sit-Up', 'Taschenmesser-Sit-up', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.', 'As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.', 'While inhaling, lower your arms and legs back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Janda_Sit-Up', 'Janda Sit-Up', 'Janda-Sit-up', array['abdominals']::text[], '{}'::text[], 'body only', array['Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.', 'As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.', 'As you inhale, slowly go back in a controlled manner to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Jefferson_Squats', 'Jefferson Squats', 'Jefferson-Kniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back', 'traps']::text[], 'barbell', array['Place a barbell on the floor.', 'Stand in the middle of the bar length wise.', 'Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.', 'Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).', 'Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.', 'Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.', 'Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm''s length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs; not your arms.']::text[]),
    ('Jerk_Balance', 'Jerk Balance', 'Jerk Balance', array['shoulders']::text[], array['glutes', 'hamstrings', 'quadriceps', 'triceps']::text[], 'barbell', array['This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.', 'Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.', 'Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.']::text[]),
    ('Jerk_Dip_Squat', 'Jerk Dip Squat', 'Jerk Dip Squat', array['quadriceps']::text[], array['abdominals', 'calves']::text[], 'barbell', array['This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.', 'Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.']::text[])
  ) as v(source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  on conflict (user_id, source, source_id) do update set
    name_en = excluded.name_en,
    name_de = excluded.name_de,
    primary_muscles = excluded.primary_muscles,
    secondary_muscles = excluded.secondary_muscles,
    equipment = excluded.equipment,
    instructions_en = excluded.instructions_en;

  insert into fit_exercises
    (user_id, source, source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  select uid, 'free-exercise-db', v.source_id, v.name_en, v.name_de, v.primary_muscles, v.secondary_muscles, v.equipment, v.instructions_en
  from (values
    ('Keg_Load', 'Keg Load', 'Fass-Laden (Keg Load)', array['lower back']::text[], array['abdominals', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'shoulders', 'traps']::text[], 'other', array['To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.', 'Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.', 'The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.', 'Return to the starting position to retrieve the next keg, and repeat until the event is completed.']::text[]),
    ('Kettlebell_Arnold_Press', 'Kettlebell Arnold Press', 'Kettlebell-Arnold-Press', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.', 'Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.', 'Return the kettlebell to the starting position, with the palm facing in.']::text[]),
    ('Kettlebell_Dead_Clean', 'Kettlebell Dead Clean', 'Kettlebell-Dead-Clean', array['hamstrings']::text[], array['calves', 'glutes', 'lower back', 'quadriceps', 'traps']::text[], 'kettlebells', array['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.']::text[]),
    ('Kettlebell_Figure_8', 'Kettlebell Figure 8', 'Kettlebell Figure 8 (Achter)', array['abdominals']::text[], array['hamstrings', 'shoulders']::text[], 'kettlebells', array['Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.']::text[]),
    ('Kettlebell_Halo', 'Kettlebell Halo', 'Kettlebell-Halo', array['shoulders']::text[], array['traps', 'middle back', 'abdominals', 'triceps']::text[], 'kettlebells', array['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.', 'Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.', 'Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight.']::text[]),
    ('Kettlebell_Halo_With_Overhead_Extension', 'Kettlebell Halo with Overhead Extension', 'Kettlebell-Halo mit Überkopfstreckung', array['shoulders', 'triceps']::text[], array['traps', 'middle back', 'abdominals']::text[], 'kettlebells', array['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.', 'From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.', 'Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.', 'Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises.']::text[]),
    ('Kettlebell_Hang_Clean', 'Kettlebell Hang Clean', 'Kettlebell-Umsetzen aus dem Hang', array['hamstrings']::text[], array['calves', 'glutes', 'lower back', 'shoulders', 'traps']::text[], 'kettlebells', array['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times.']::text[]),
    ('Kettlebell_One-Legged_Deadlift', 'Kettlebell One-Legged Deadlift', 'Einbeiniges Kettlebell-Kreuzheben', array['hamstrings']::text[], array['glutes', 'lower back']::text[], 'kettlebells', array['Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.', 'Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.', 'Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.']::text[]),
    ('Kettlebell_Overhead_Triceps_Extension', 'Kettlebell Overhead Triceps Extension', 'Kettlebell-Trizeps-Extension über Kopf', array['triceps']::text[], array['shoulders', 'abdominals']::text[], 'kettlebells', array['Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.', 'Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.', 'Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.', 'Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.', 'Keep your ribcage down and avoid arching your lower back as you extend.']::text[]),
    ('Kettlebell_Pass_Between_The_Legs', 'Kettlebell Pass Between The Legs', 'Kettlebell durch die Beine reichen', array['abdominals']::text[], array['glutes', 'hamstrings', 'shoulders']::text[], 'kettlebells', array['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.']::text[]),
    ('Kettlebell_Pirate_Ships', 'Kettlebell Pirate Ships', 'Kettlebell Pirate Ships', array['shoulders']::text[], array['abdominals']::text[], 'kettlebells', array['With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.', 'Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.', 'Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.', 'Repeat for the desired amount of repetitions.']::text[]),
    ('Kettlebell_Pistol_Squat', 'Kettlebell Pistol Squat', 'Kettlebell-Pistol-Squat', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'shoulders']::text[], 'kettlebells', array['Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.', 'Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.', 'Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.', 'Lower yourself again and repeat.']::text[]),
    ('Kettlebell_Seated_Press', 'Kettlebell Seated Press', 'Sitzendes Kettlebell-Drücken', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Sit on the floor and spread your legs out comfortably.', 'Clean one kettlebell to your shoulder.', 'Press the kettlebell up and out until it is locked out overhead. Return to the starting position.']::text[]),
    ('Kettlebell_Seesaw_Press', 'Kettlebell Seesaw Press', 'Kettlebell-Seesaw-Press', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Clean two kettlebells two your shoulders.', 'Press one kettlebell.', 'Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.']::text[]),
    ('Kettlebell_Sumo_High_Pull', 'Kettlebell Sumo High Pull', 'Kettlebell-Sumo-High-Pull', array['traps']::text[], array['adductors', 'glutes', 'hamstrings', 'quadriceps', 'shoulders']::text[], 'kettlebells', array['Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.', 'Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.']::text[]),
    ('Kettlebell_Thruster', 'Kettlebell Thruster', 'Kettlebell-Thruster', array['shoulders']::text[], array['quadriceps', 'triceps']::text[], 'kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.', 'Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.', 'At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.', 'As you begin the next repetition, return the weights to the shoulders.']::text[]),
    ('Kettlebell_Turkish_Get-Up_Lunge_style', 'Kettlebell Turkish Get-Up (Lunge style)', 'Türkisches Aufstehen mit Kettlebell (Ausfallschritt-Variante)', array['shoulders']::text[], array['abdominals', 'hamstrings', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.', 'While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[]),
    ('Kettlebell_Turkish_Get-Up_Squat_style', 'Kettlebell Turkish Get-Up (Squat style)', 'Türkisches Aufstehen mit Kettlebell (Kniebeuge-Variante)', array['shoulders']::text[], array['abdominals', 'calves', 'hamstrings', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.', 'Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[]),
    ('Kettlebell_Windmill', 'Kettlebell Windmill', 'Kettlebell-Windmühle', array['abdominals']::text[], array['glutes', 'hamstrings', 'shoulders', 'triceps']::text[], 'kettlebells', array['Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after reaching the ground and reverse the motion back to the starting position.']::text[]),
    ('Kipping_Muscle_Up', 'Kipping Muscle Up', 'Kipping Muscle-up', array['lats']::text[], array['abdominals', 'biceps', 'forearms', 'middle back', 'shoulders', 'traps', 'triceps']::text[], 'other', array['Grip the rings using a false grip, with the base of your palms on top of the rings.', 'Begin with a movement swinging your legs backward slightly.', 'Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.', 'Maintaining control and stability, extend through the elbow to complete the motion.', 'Use care when lowering yourself to the ground.']::text[]),
    ('Knee_Hip_Raise_On_Parallel_Bars', 'Knee/Hip Raise On Parallel Bars', 'Knie-/Hüftheben am Barren', array['abdominals']::text[], '{}'::text[], 'other', array['Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.', 'The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.', 'Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.', 'Slowly go back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'Kniender Kabel-Crunch mit wechselseitiger Drehung', array['abdominals']::text[], '{}'::text[], 'cable', array['Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.', 'Grab the rope with both hands and kneel approximately two feet back from the tower.', 'Position the rope behind your head with your hands by your ears.', 'Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.', 'Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.', 'Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same movement as before, but alternate the other elbow to the opposite knee.', 'Continue this series of movements to failure.']::text[]),
    ('Kneeling_Cable_Triceps_Extension', 'Kneeling Cable Triceps Extension', 'Kniende Trizeps-Extension am Kabelzug', array['triceps']::text[], '{}'::text[], 'cable', array['Place a bench sideways in front of a high pulley machine.', 'Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.', 'Face away from the machine and kneel.', 'Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.', 'While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Kneeling_High_Pulley_Row', 'Kneeling High Pulley Row', 'Kniendes Rudern am hohen Kabelzug', array['lats']::text[], array['biceps', 'middle back']::text[], 'cable', array['Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.', 'Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.', 'After pausing briefly, slowly return to the starting position.']::text[]),
    ('Kneeling_Jump_Squat', 'Kneeling Jump Squat', 'Kniende Sprung-Kniebeuge', array['glutes']::text[], array['calves', 'hamstrings', 'quadriceps']::text[], 'barbell', array['Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.', 'Sit back with your hips until your glutes touch your feet, keeping your head and chest up.', 'Explode up with your hips, generating enough power to land with your feet flat on the floor.', 'Continue with the squat by driving through your heels and extending the knees to come to a standing position.']::text[]),
    ('Kneeling_Single-Arm_High_Pulley_Row', 'Kneeling Single-Arm High Pulley Row', 'Kniendes einarmiges Rudern am hohen Kabelzug', array['lats']::text[], array['biceps', 'middle back']::text[], 'cable', array['Attach a single handle to a high pulley and make your weight selection.', 'Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.', 'Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.', 'After a brief pause, return to the starting position.']::text[]),
    ('Kneeling_Squat', 'Kneeling Squat', 'Kniende Kniebeuge', array['glutes']::text[], array['abdominals', 'hamstrings', 'lower back']::text[], 'barbell', array['Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.', 'With your head looking forward, sit back with your butt until you touch your calves.', 'Reverse the motion, returning the torso to an upright position.']::text[]),
    ('Landmine_180s', 'Landmine 180''s', 'Landmine 180er', array['abdominals']::text[], array['glutes', 'lower back', 'shoulders']::text[], 'barbell', array['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.', 'Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.', 'Reverse the motion to swing the weight all the way to the opposite side.', 'Continue alternating the movement until the set is complete.']::text[]),
    ('Landmine_Linear_Jammer', 'Landmine Linear Jammer', 'Landmine Linear Jammer', array['shoulders']::text[], array['abdominals', 'calves', 'chest', 'hamstrings', 'quadriceps', 'triceps']::text[], 'barbell', array['Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.', 'Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.', 'In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.', 'Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.', 'Return to the starting position.']::text[]),
    ('Lateral_Raise_-_With_Bands', 'Lateral Raise - With Bands', 'Seitheben mit Band', array['shoulders']::text[], '{}'::text[], 'bands', array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Leg-Over_Floor_Press', 'Leg-Over Floor Press', 'Bodendrücken mit Beinüberkreuzung', array['chest']::text[], array['shoulders', 'triceps']::text[], 'kettlebells', array['Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.', 'Press the kettlebll into a locked out position.', 'Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.']::text[]),
    ('Leg_Extensions', 'Leg Extensions', 'Beinstrecker', array['quadriceps']::text[], '{}'::text[], 'machine', array['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.']::text[]),
    ('Leg_Lift', 'Leg Lift', 'Beinheben', array['glutes']::text[], array['hamstrings']::text[], 'body only', array['While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.', 'With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.', 'Slowly bring the raised leg back to the floor as you breathe in.', 'Repeat for the recommended amount of repetitions.', 'Repeat the movement with the opposite leg.']::text[]),
    ('Leg_Press', 'Leg Press', 'Beinpresse', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[]),
    ('Leg_Pull-In', 'Leg Pull-In', 'Beinanziehen', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.', 'Return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Leverage_Chest_Press', 'Leverage Chest Press', 'Brustpresse (Hebelmaschine)', array['chest']::text[], array['shoulders', 'triceps']::text[], 'machine', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.', 'Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
    ('Leverage_Deadlift', 'Leverage Deadlift', 'Kreuzheben (Hebelmaschine)', array['quadriceps']::text[], array['glutes', 'hamstrings']::text[], 'machine', array['Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.', 'Return the weight to the starting position.']::text[]),
    ('Leverage_Decline_Chest_Press', 'Leverage Decline Chest Press', 'Negativ-Brustpresse (Hebelmaschine)', array['chest']::text[], array['shoulders', 'triceps']::text[], 'machine', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
    ('Leverage_High_Row', 'Leverage High Row', 'Hohes Rudern (Hebelmaschine)', array['middle back']::text[], array['lats']::text[], 'machine', array['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position.', 'For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[]),
    ('Leverage_Incline_Chest_Press', 'Leverage Incline Chest Press', 'Schräge Brustpresse (Hebelmaschine)', array['chest']::text[], array['shoulders', 'triceps']::text[], 'machine', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
    ('Leverage_Iso_Row', 'Leverage Iso Row', 'Iso-Rudern (Hebelmaschine)', array['lats']::text[], array['biceps', 'middle back']::text[], 'machine', array['Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[]),
    ('Leverage_Shoulder_Press', 'Leverage Shoulder Press', 'Schulterpresse (Hebelmaschine)', array['shoulders']::text[], array['triceps']::text[], 'machine', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.', 'Press the handles upward by extending through the elbow.', 'After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
    ('Leverage_Shrug', 'Leverage Shrug', 'Schulterzucken (Hebelmaschine)', array['traps']::text[], array['forearms']::text[], 'machine', array['Load the pins to an appropriate weight. Position yourself directly between the handles.', 'Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.', 'Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.', 'Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.', 'Pause at the top of the motion, and then return the weight to the starting position.']::text[]),
    ('Log_Lift', 'Log Lift', 'Baumstamm-Heben (Log Lift)', array['shoulders']::text[], array['abdominals', 'chest', 'glutes', 'hamstrings', 'lower back', 'middle back', 'quadriceps', 'traps', 'triceps']::text[], 'other', array['Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.', 'Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.', 'Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground.']::text[]),
    ('London_Bridges', 'London Bridges', 'London Bridges', array['lats']::text[], array['biceps', 'forearms', 'middle back']::text[], 'other', array['Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.', 'Stand on the bar, using the rope to balance yourself. This will be your starting position.', 'Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.', 'Keeping your body straight, reverse the motion, going hand over hand back to the starting position.']::text[]),
    ('Low_Cable_Crossover', 'Low Cable Crossover', 'Cable Crossover von unten', array['chest']::text[], array['shoulders']::text[], 'cable', array['To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.', 'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.', 'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.', 'Return your arms back to the starting position after a brief pause.']::text[]),
    ('Low_Cable_Triceps_Extension', 'Low Cable Triceps Extension', 'Trizeps-Extension am unteren Kabelzug', array['triceps']::text[], '{}'::text[], 'cable', array['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.', 'Grab the outside of the rope ends with your palms facing each other (neutral grip).', 'Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.', 'As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.', 'As you breathe in slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Low_Pulley_Row_To_Neck', 'Low Pulley Row To Neck', 'Rudern zum Nacken am unteren Kabelzug', array['shoulders']::text[], array['biceps', 'middle back', 'traps']::text[], 'cable', array['Sit on a low pulley row machine with a rope attachment.', 'Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.', 'While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.', 'After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lunge_Pass_Through', 'Lunge Pass Through', 'Ausfallschritt mit Durchreichen', array['hamstrings']::text[], array['calves', 'glutes', 'quadriceps']::text[], 'kettlebells', array['Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.', 'Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.', 'As you lunge, pass the kettlebell under your front leg to your opposite hand.', 'Pressing through the heel of your foot, return to the starting position.', 'Repeat the movement for the recommended amount of repetitions, alternating legs.']::text[]),
    ('Lunge_Sprint', 'Lunge Sprint', 'Ausfallschritt-Sprint', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.', 'Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.', 'At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Cable_Curl', 'Lying Cable Curl', 'Liegender Curl am Kabelzug', array['biceps']::text[], '{}'::text[], 'cable', array['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.', 'Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.', 'With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.', 'While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.', 'After a second squeeze at the top of the movement, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Cambered_Barbell_Row', 'Lying Cambered Barbell Row', 'Liegendes Rudern mit gebogener Langhantel', array['middle back']::text[], array['biceps', 'lats', 'traps']::text[], 'barbell', array['Place a cambered bar underneath an exercise bench.', 'Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.', 'As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.', 'After a second hold at the top, lower back down to the starting position slowly as you inhale.']::text[]),
    ('Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'Liegender Curl am hohen Kabelzug, enger Griff', array['biceps']::text[], '{}'::text[], 'cable', array['Place a flat bench in front of a high pulley or lat pulldown machine.', 'Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.', 'Lie on your back with your head over the end of the bench.', 'Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.', 'As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.', 'Return to starting position slowly.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Liegende Langhantel-Trizeps-Extension hinter den Kopf, enger Griff', array['triceps']::text[], '{}'::text[], 'barbell', array['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.', 'As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'Liegendes Langhantel-Trizepsdrücken zum Kinn, enger Griff', array['triceps']::text[], '{}'::text[], 'e-z curl bar', array['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.', 'As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Dumbbell_Tricep_Extension', 'Lying Dumbbell Tricep Extension', 'Liegende Kurzhantel-Trizeps-Extension', array['triceps']::text[], array['chest', 'shoulders']::text[], 'dumbbell', array['Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.', 'As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.', 'At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Face_Down_Plate_Neck_Resistance', 'Lying Face Down Plate Neck Resistance', 'Nackentraining mit Scheibe, Bauchlage', array['neck']::text[], '{}'::text[], 'other', array['Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.', 'While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Face_Up_Plate_Neck_Resistance', 'Lying Face Up Plate Neck Resistance', 'Nackentraining mit Scheibe, Rückenlage', array['neck']::text[], '{}'::text[], 'other', array['Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.', 'While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_High_Bench_Barbell_Curl', 'Lying High Bench Barbell Curl', 'Langhantel-Curl liegend auf der hohen Bank', array['biceps']::text[], '{}'::text[], 'barbell', array['Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.', 'While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.', 'As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Leg_Curls', 'Lying Leg Curls', 'Liegender Beinbeuger', array['hamstrings']::text[], '{}'::text[], 'machine', array['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Machine_Squat', 'Lying Machine Squat', 'Liegende Kniebeuge (Maschine)', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.', 'Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.', 'Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.', 'While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.', 'Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_One-Arm_Lateral_Raise', 'Lying One-Arm Lateral Raise', 'Einarmiges liegendes Seitheben', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.', 'Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.', 'Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbell to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Rear_Delt_Raise', 'Lying Rear Delt Raise', 'Liegendes Heben für die hintere Schulter', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['While holding a dumbbell in each hand, lay with your chest down on a flat bench.', 'Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.', 'Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbells to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
    ('Lying_Supine_Dumbbell_Curl', 'Lying Supine Dumbbell Curl', 'Kurzhantel-Curl in Rückenlage', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.', 'Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).', 'While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.', 'As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.', 'Return back to the starting position very slowly.']::text[]),
    ('Lying_T-Bar_Row', 'Lying T-Bar Row', 'Liegendes T-Bar-Rudern', array['middle back']::text[], array['biceps', 'lats']::text[], 'machine', array['Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.', 'Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.', 'Lift the bar off the rack and extend your arms in front of you. This will be your starting position.', 'As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.', 'After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Lying_Triceps_Press', 'Lying Triceps Press', 'Liegendes Trizepsdrücken (Stirndrücken)', array['triceps']::text[], '{}'::text[], 'e-z curl bar', array['Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.', 'Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.', 'As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.', 'At that point, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Machine_Bench_Press', 'Machine Bench Press', 'Bankdrücken an der Maschine', array['chest']::text[], array['shoulders', 'triceps']::text[], 'machine', array['Sit down on the Chest Press Machine and select the weight.', 'Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.', 'Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.', 'Now bring the handles back towards you as you breathe in.', 'Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.', 'Repeat for the recommended amount of reps.', 'When finished step on the lever again and slowly get the handles back to their original place.']::text[]),
    ('Machine_Bicep_Curl', 'Machine Bicep Curl', 'Bizepscurl an der Maschine', array['biceps']::text[], '{}'::text[], 'machine', array['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.', 'Pause at the top of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[]),
    ('Machine_Preacher_Curls', 'Machine Preacher Curls', 'Scott-Curl an der Maschine', array['biceps']::text[], '{}'::text[], 'machine', array['Sit down on the Preacher Curl Machine and select the weight.', 'Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.', 'Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Machine_Shoulder_Military_Press', 'Machine Shoulder (Military) Press', 'Schulterdrücken an der Maschine', array['shoulders']::text[], array['triceps']::text[], 'machine', array['Sit down on the Shoulder Press Machine and select the weight.', 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.', 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Machine_Triceps_Extension', 'Machine Triceps Extension', 'Trizepsstrecken an der Maschine', array['triceps']::text[], '{}'::text[], 'machine', array['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.', 'Pause at the completion of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[]),
    ('Middle_Back_Shrug', 'Middle Back Shrug', 'Schulterzucken für den mittleren Rücken', array['middle back']::text[], '{}'::text[], 'dumbbell', array['Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.', 'As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.', 'As you inhale go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Mixed_Grip_Chin', 'Mixed Grip Chin', 'Klimmzug im Wechselgriff', array['middle back']::text[], array['biceps', 'lats']::text[], 'other', array['Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.', 'Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.', 'After a second contraction at the top, start to slowly come down as you inhale.', 'Repeat for the recommended amount of repetitions.', 'On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.']::text[]),
    ('Monster_Walk', 'Monster Walk', 'Monster Walk', array['abductors']::text[], '{}'::text[], 'bands', array['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.', 'To begin, take short steps forward alternating your left and right foot.', 'After several steps, do just the opposite and walk backward to where you started.']::text[]),
    ('Muscle_Snatch', 'Muscle Snatch', 'Muscle Snatch', array['hamstrings']::text[], array['glutes', 'lower back', 'quadriceps', 'shoulders', 'triceps']::text[], 'barbell', array['Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.', 'Continue raising the bar to the overhead position, without rebending the knees.']::text[]),
    ('Muscle_Up', 'Muscle Up', 'Muscle-up', array['lats']::text[], array['abdominals', 'biceps', 'forearms', 'middle back', 'shoulders', 'traps', 'triceps']::text[], 'other', array['Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.', 'As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.', 'Maintaining control and stability, extend through the elbow to complete the motion.', 'Use care when lowering yourself to the ground.']::text[]),
    ('Narrow_Stance_Hack_Squats', 'Narrow Stance Hack Squats', 'Hack Squat, enger Stand', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position.', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Narrow_Stance_Leg_Press', 'Narrow Stance Leg Press', 'Beinpresse, enger Stand', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'machine', array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[]),
    ('Narrow_Stance_Squats', 'Narrow Stance Squats', 'Kniebeuge, enger Stand', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Natural_Glute_Ham_Raise', 'Natural Glute Ham Raise', 'Natural Glute-Ham-Raise', array['hamstrings']::text[], array['calves', 'glutes', 'lower back']::text[], 'body only', array['Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.', 'This will be your starting position. Lower yourself under control until your knees are almost completely straight.', 'Remaining in control, raise yourself back up to the starting position.', 'If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.']::text[]),
    ('Neck_Press', 'Neck Press', 'Nackendrücken', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
    ('Oblique_Crunches', 'Oblique Crunches', 'Schräge Crunches', array['abdominals']::text[], '{}'::text[], 'body only', array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.', 'Make sure your feet are elevated and resting on a flat surface.', 'Now lift the shoulder in which your hand is touching your head.', 'Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.', 'After your knee touches your elbow, lower your body until you have reached the starting position.', 'Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[]),
    ('Oblique_Crunches_-_On_The_Floor', 'Oblique Crunches - On The Floor', 'Schräge Crunches am Boden', array['abdominals']::text[], '{}'::text[], 'body only', array['Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.', 'Place your left hand behind your head.', 'Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.', 'Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.', 'Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.']::text[]),
    ('Olympic_Squat', 'Olympic Squat', 'Olympische Kniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.', 'Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.', 'At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.']::text[]),
    ('One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'Einarmiges Kurzhantelrudern', array['middle back']::text[], array['biceps', 'lats', 'shoulders']::text[], 'dumbbell', array['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.']::text[]),
    ('One-Arm_Flat_Bench_Dumbbell_Flye', 'One-Arm Flat Bench Dumbbell Flye', 'Einarmige Kurzhantel-Fliegende auf der Flachbank', array['chest']::text[], '{}'::text[], 'dumbbell', array['Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.', 'By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.', 'Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.', 'Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
    ('One-Arm_High-Pulley_Cable_Side_Bends', 'One-Arm High-Pulley Cable Side Bends', 'Einarmige Seitbeugen am hohen Kabelzug', array['abdominals']::text[], '{}'::text[], 'cable', array['Connect a standard handle to a tower. Move cable to highest pulley position.', 'Stand with side to cable. With one hand, reach up and grab handle with underhand grip.', 'Pull down cable until elbow touches your side and the handle is by your shoulder.', 'Position feet hip-width apart. Place free hand on hip to help gauge pivot point.', 'Keep arm in static position. Contract oblique to bring the weight down in a side crunch.', 'Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
    ('One-Arm_Incline_Lateral_Raise', 'One-Arm Incline Lateral Raise', 'Einarmiges Seitheben an der Schrägbank', array['shoulders']::text[], '{}'::text[], 'dumbbell', array['Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.', 'Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.', 'While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.', 'While inhaling lower the weight across your body back into the starting position.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.']::text[]),
    ('One-Arm_Kettlebell_Clean', 'One-Arm Kettlebell Clean', 'Einarmiges Kettlebell-Umsetzen', array['hamstrings']::text[], array['glutes', 'lower back', 'shoulders', 'traps']::text[], 'kettlebells', array['Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.', 'Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Return the weight to the starting position.']::text[]),
    ('One-Arm_Kettlebell_Clean_and_Jerk', 'One-Arm Kettlebell Clean and Jerk', 'Einarmiges Kettlebell-Umsetzen und Stoßen', array['shoulders']::text[], '{}'::text[], 'kettlebells', array['Hold a kettlebell by the handle.', 'Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight.', 'Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition.']::text[]),
    ('One-Arm_Kettlebell_Floor_Press', 'One-Arm Kettlebell Floor Press', 'Einarmiges Kettlebell-Bodendrücken', array['chest']::text[], array['triceps']::text[], 'kettlebells', array['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.', 'Press the kettlebell straight up toward the ceiling, rotating your wrist.', 'Lower the kettlebell back to the starting position and repeat.']::text[]),
    ('One-Arm_Kettlebell_Jerk', 'One-Arm Kettlebell Jerk', 'Einarmiges Kettlebell-Stoßen', array['shoulders']::text[], array['calves', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.', 'Lower the weight to perform the next repetition.']::text[]),
    ('One-Arm_Kettlebell_Military_Press_To_The_Side', 'One-Arm Kettlebell Military Press To The Side', 'Einarmiges Kettlebell-Schulterdrücken zur Seite', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.', 'Look at the kettlebell and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[]),
    ('One-Arm_Kettlebell_Para_Press', 'One-Arm Kettlebell Para Press', 'Einarmiger Kettlebell-Para-Press', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[]),
    ('One-Arm_Kettlebell_Push_Press', 'One-Arm Kettlebell Push Press', 'Einarmiger Kettlebell-Push-Press', array['shoulders']::text[], array['calves', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Lower the weight to perform the next repetition.']::text[]),
    ('One-Arm_Kettlebell_Row', 'One-Arm Kettlebell Row', 'Einarmiges Kettlebell-Rudern', array['middle back']::text[], array['biceps', 'lats']::text[], 'kettlebells', array['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.']::text[]),
    ('One-Arm_Kettlebell_Snatch', 'One-Arm Kettlebell Snatch', 'Einarmiges Kettlebell-Reißen', array['shoulders']::text[], array['calves', 'glutes', 'hamstrings', 'lower back', 'traps', 'triceps']::text[], 'kettlebells', array['Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.', 'Look straight ahead and swing the kettlebell back between your legs.', 'Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.']::text[]),
    ('One-Arm_Kettlebell_Split_Jerk', 'One-Arm Kettlebell Split Jerk', 'Einarmiges Kettlebell-Split-Jerk', array['shoulders']::text[], array['glutes', 'hamstrings', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.', 'Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.']::text[]),
    ('One-Arm_Kettlebell_Split_Snatch', 'One-Arm Kettlebell Split Snatch', 'Einarmiges Kettlebell-Split-Snatch', array['shoulders']::text[], array['hamstrings', 'quadriceps']::text[], 'kettlebells', array['Hold a kettlebell in one hand by the handle.', 'Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.', 'After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.', 'Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.']::text[]),
    ('One-Arm_Kettlebell_Swings', 'One-Arm Kettlebell Swings', 'Einarmiger Kettlebell-Swing', array['hamstrings']::text[], array['calves', 'glutes', 'lower back', 'shoulders']::text[], 'kettlebells', '{}'::text[])
  ) as v(source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  on conflict (user_id, source, source_id) do update set
    name_en = excluded.name_en,
    name_de = excluded.name_de,
    primary_muscles = excluded.primary_muscles,
    secondary_muscles = excluded.secondary_muscles,
    equipment = excluded.equipment,
    instructions_en = excluded.instructions_en;
end
$seed$;
